 function execute(work,input,hooks={}){requireValue(!running&&!retiring&&!closed,'One native TNT GPU bank job at a time');const signal=AbortSignal.any([controller.signal,...(hooks.signal?[hooks.signal]:[])]),task=Promise.resolve().then(async()=>{current(signal);await retry();current(signal);const job={credits:[],output:null,parts:0,peak:0,writeBytes:0,readBytes:0};jobs.add(job);let published=false;try{const value=await work(job,input,signal,hooks.onProgress);current(signal);value.gpu={devices:1,allocations:job.parts*7,peakAccountedBytes:job.peak,accounting:'same explicit native GPU buffers; excludes driver/compiler residency',errors:[]};value.timings={gpuWriteBytes:job.writeBytes,gpuReadBytes:job.readBytes};freeJob(job);published=true;return value;}catch(primary){needsDeviceRetirement=true;await retireCompositeOwners([async()=>{await retireChildren();await retireDevice();job.output?.release();freeJob(job);} ],{primary});throw primary;}finally{if(!published&&!children.size&&!needsDeviceRetirement){job.output?.release();freeJob(job);}}});running=task;task.then(()=>{if(running===task)running=undefined;},()=>{if(running===task)running=undefined;});return task;}
