    let loan,failed=false,primary;try{loan=await nativePart(job,packed,weights,b,{channels:ci,height,width,outChannels:count,referenceLayout:{inputShape:[1,ci,height,width],weightShape:[count,ci,1,1],padding:0,stride:1,groups:1,biasAfterRanges:after?[[0,n]]:[]}},signal,onProgress);for(let c=0;c<count;c++)data.set(loan.data.subarray(c*n,(c+1)*n),(start+c)*rows+row);await retireChild(loan);loan=undefined;free();}catch(error){failed=true;primary=error;throw error;}finally{await retireCompositeOwners(loan?[()=>retireChild(loan)]:[],failed?{primary}:{});}await controlCheckpoint(signal);
